using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Platform.Persistence.Entities;

namespace Platform.Persistence.Configurations;

internal sealed class PaymentConfiguration(bool sqlite) : IEntityTypeConfiguration<Payment>
{
    public void Configure(EntityTypeBuilder<Payment> row)
    {
        row.ToTable("payments", sqlite ? null : "shop", table =>
        {
            if (sqlite)
            {
                table.HasCheckConstraint("ck_payments_1", "id IS NULL OR akanti_uuid(id)");
                table.HasCheckConstraint("ck_payments_2", "order_id IS NULL OR akanti_uuid(order_id)");
                table.HasCheckConstraint("ck_payments_3", "topup_user_id IS NULL OR akanti_uuid(topup_user_id)");
                table.HasCheckConstraint("ck_payments_4", "payment_method IN ('crypto','bank')");
                table.HasCheckConstraint("ck_payments_5", "quote_currency IN ('USD','TOMAN')");
                table.HasCheckConstraint("ck_payments_6", "amount_due IS NULL OR (akanti_decimal(amount_due)=1)");
                table.HasCheckConstraint("ck_payments_7", "akanti_decimal_compare(amount_due,'0') > 0");
                table.HasCheckConstraint("ck_payments_8", "amount_received IS NULL OR (akanti_decimal(amount_received)=1)");
                table.HasCheckConstraint("ck_payments_9", "akanti_decimal_compare(amount_received,'0') >= 0");
                table.HasCheckConstraint("ck_payments_10", "provider_code IS NULL OR (length(provider_code) BETWEEN 1 AND 160 AND trim(provider_code)<>'')");
                table.HasCheckConstraint("ck_payments_11", "provider_payment_ref IS NULL OR (length(provider_payment_ref) BETWEEN 1 AND 160 AND trim(provider_payment_ref)<>'')");
                table.HasCheckConstraint("ck_payments_12", "hosted_invoice_ref IS NULL OR (length(hosted_invoice_ref) BETWEEN 1 AND 160 AND trim(hosted_invoice_ref)<>'')");
                table.HasCheckConstraint("ck_payments_13", "length(hosted_invoice_ref) BETWEEN 1 AND 64 AND hosted_invoice_ref NOT GLOB '*[^0-9]*'");
                table.HasCheckConstraint("ck_payments_14", "hosted_invoice_url IS NULL OR (length(hosted_invoice_url) BETWEEN 1 AND 1024)");
                table.HasCheckConstraint("ck_payments_15", "idempotency_ref IS NULL OR (length(idempotency_ref) BETWEEN 1 AND 160 AND trim(idempotency_ref)<>'')");
                table.HasCheckConstraint("ck_payments_16", "network_asset IN ('USDTTRC20','USDTBSC')");
                table.HasCheckConstraint("ck_payments_17", "expected_network_amount IS NULL OR (akanti_decimal(expected_network_amount)=1)");
                table.HasCheckConstraint("ck_payments_18", "akanti_decimal_compare(expected_network_amount,'0') > 0");
                table.HasCheckConstraint("ck_payments_19", "ipn_key_id IS NULL OR (length(ipn_key_id) BETWEEN 1 AND 160 AND trim(ipn_key_id)<>'')");
                table.HasCheckConstraint("ck_payments_20", "length(ipn_signature)=64");
                table.HasCheckConstraint("ck_payments_21", "length(ipn_payload_sha256)=32");
                table.HasCheckConstraint("ck_payments_22", "network_amount IS NULL OR (akanti_decimal(network_amount)=1)");
                table.HasCheckConstraint("ck_payments_23", "akanti_decimal_compare(network_amount,'0') >= 0");
                table.HasCheckConstraint("ck_payments_24", "provider_confirmations >= 0");
                table.HasCheckConstraint("ck_payments_25", "status IN ('created','awaiting','observed','confirming','settled','rejected','expired','review')");
                table.HasCheckConstraint("ck_payments_26", "provider_status_code IS NULL OR (length(provider_status_code) BETWEEN 1 AND 160 AND trim(provider_status_code)<>'')");
                table.HasCheckConstraint("ck_payments_28", "receipt_asset_ref IS NULL OR (length(receipt_asset_ref) BETWEEN 1 AND 1024)");
                table.HasCheckConstraint("ck_payments_29", "review_admin_id IS NULL OR akanti_uuid(review_admin_id)");
                table.HasCheckConstraint("ck_payments_30", "review_reason IS NULL OR (length(review_reason)<=16384)");
                table.HasCheckConstraint("ck_payments_31", "compensating_wallet_entry_id IS NULL OR akanti_uuid(compensating_wallet_entry_id)");
                table.HasCheckConstraint("ck_payments_32", "evidence_asset_ref IS NULL OR (length(evidence_asset_ref) BETWEEN 1 AND 1024)");
                table.HasCheckConstraint("ck_payments_33", "length(pending_evidence) BETWEEN 2 AND 65536");
                table.HasCheckConstraint("ck_payments_35", "length(evidence_digest)=32");
                table.HasCheckConstraint("ck_payments_36", "legacy_kind IS NULL OR (length(legacy_kind) BETWEEN 1 AND 160 AND trim(legacy_kind)<>'')");
                table.HasCheckConstraint("ck_payments_37", "((order_id IS NOT NULL) + (topup_user_id IS NOT NULL))=1");
                table.HasCheckConstraint("ck_payments_40", "(evidence_asset_ref IS NOT NULL OR pending_evidence IS NOT NULL) = (evidence_digest IS NOT NULL)");
                table.HasCheckConstraint("ck_payments_41", "pending_evidence IS NULL OR (evidence_asset_ref IS NULL AND order_id IS NOT NULL AND ipn_key_id IS NOT NULL AND first_payment_observed_at IS NOT NULL AND status IN ('confirming','review'))");
                table.HasCheckConstraint("ck_payments_42", "((review_admin_id IS NOT NULL) + (reviewed_at IS NOT NULL) + (review_reason IS NOT NULL)) IN (0,3)");
                table.HasCheckConstraint("ck_payments_43", "provider_payment_ref IS NULL OR provider_code IS NOT NULL");
                table.HasCheckConstraint("ck_payments_44", "hosted_invoice_started_at IS NULL OR akanti_utc_time(hosted_invoice_started_at)");
                table.HasCheckConstraint("ck_payments_45", "((hosted_invoice_ref IS NOT NULL) + (hosted_invoice_url IS NOT NULL)) IN (0,2)");
                table.HasCheckConstraint("ck_payments_46", "hosted_invoice_started_at IS NULL OR (payment_method='crypto' AND provider_code IS NOT DISTINCT FROM 'nowpayments')");
                table.HasCheckConstraint("ck_payments_47", "hosted_invoice_ref IS NULL OR hosted_invoice_started_at IS NOT NULL");
                table.HasCheckConstraint("ck_payments_48", "(payment_method='crypto' AND quote_currency='USD' AND network_asset IS NOT NULL AND bank_destination IS NULL) OR\n           (payment_method='bank' AND quote_currency='TOMAN' AND order_id IS NOT NULL AND (bank_destination IS NOT NULL OR coalesce(legacy_kind='manual_deposit',false)) AND network_asset IS NULL AND network_amount IS NULL AND provider_confirmations IS NULL)");
                table.HasCheckConstraint("ck_payments_49", "topup_user_id IS NULL OR payment_method='crypto'");
                table.HasCheckConstraint("ck_payments_50", "status <> 'settled' OR confirmed_at IS NOT NULL");
                table.HasCheckConstraint("ck_payments_51", "((ipn_key_id IS NOT NULL) + (ipn_signature IS NOT NULL) + (ipn_payload_sha256 IS NOT NULL) + (ipn_verified_at IS NOT NULL)) IN (0,4)");
                table.HasCheckConstraint("ck_payments_52", "ipn_key_id IS NULL OR (payment_method='crypto' AND provider_payment_ref IS NOT NULL AND expected_network_amount IS NOT NULL AND (evidence_asset_ref IS NOT NULL OR pending_evidence IS NOT NULL))");
                table.HasCheckConstraint("ck_payments_53", "expected_network_amount IS NULL OR payment_method='crypto'");
                table.HasCheckConstraint("ck_payments_54", "ipn_verified_at IS NULL OR akanti_utc_time(ipn_verified_at)");
                table.HasCheckConstraint("ck_payments_55", "first_payment_observed_at IS NULL OR akanti_utc_time(first_payment_observed_at)");
                table.HasCheckConstraint("ck_payments_56", "confirmed_at IS NULL OR akanti_utc_time(confirmed_at)");
                table.HasCheckConstraint("ck_payments_57", "reviewed_at IS NULL OR akanti_utc_time(reviewed_at)");
                table.HasCheckConstraint("ck_payments_58", "created_at IS NULL OR akanti_utc_time(created_at)");
            }
            else
            {
                table.HasCheckConstraint("ck_payments_1", "payment_method IN ('crypto','bank')");
                table.HasCheckConstraint("ck_payments_2", "quote_currency IN ('USD','TOMAN')");
                table.HasCheckConstraint("ck_payments_3", "amount_due > 0");
                table.HasCheckConstraint("ck_payments_4", "amount_received >= 0");
                table.HasCheckConstraint("ck_payments_5", "hosted_invoice_ref ~ '^[0-9]{1,64}$'");
                table.HasCheckConstraint("ck_payments_6", "network_asset IN ('USDTTRC20','USDTBSC')");
                table.HasCheckConstraint("ck_payments_7", "expected_network_amount > 0");
                table.HasCheckConstraint("ck_payments_8", "octet_length(ipn_signature)=64");
                table.HasCheckConstraint("ck_payments_9", "octet_length(ipn_payload_sha256)=32");
                table.HasCheckConstraint("ck_payments_10", "network_amount >= 0");
                table.HasCheckConstraint("ck_payments_11", "provider_confirmations >= 0");
                table.HasCheckConstraint("ck_payments_12", "status IN ('created','awaiting','observed','confirming','settled','rejected','expired','review')");
                table.HasCheckConstraint("ck_payments_13", "octet_length(pending_evidence) BETWEEN 2 AND 65536");
                table.HasCheckConstraint("ck_payments_14", "octet_length(evidence_digest)=32");
                table.HasCheckConstraint("ck_payments_15", "num_nonnulls(order_id,topup_user_id)=1");
                table.HasCheckConstraint("ck_payments_18", "(evidence_asset_ref IS NOT NULL OR pending_evidence IS NOT NULL) = (evidence_digest IS NOT NULL)");
                table.HasCheckConstraint("ck_payments_19", "pending_evidence IS NULL OR (evidence_asset_ref IS NULL AND order_id IS NOT NULL AND ipn_key_id IS NOT NULL AND first_payment_observed_at IS NOT NULL AND status IN ('confirming','review'))");
                table.HasCheckConstraint("ck_payments_20", "num_nonnulls(review_admin_id,reviewed_at,review_reason) IN (0,3)");
                table.HasCheckConstraint("ck_payments_21", "provider_payment_ref IS NULL OR provider_code IS NOT NULL");
                table.HasCheckConstraint("ck_payments_22", "isfinite(hosted_invoice_started_at)");
                table.HasCheckConstraint("ck_payments_23", "num_nonnulls(hosted_invoice_ref,hosted_invoice_url) IN (0,2)");
                table.HasCheckConstraint("ck_payments_24", "hosted_invoice_started_at IS NULL OR (payment_method='crypto' AND provider_code IS NOT DISTINCT FROM 'nowpayments')");
                table.HasCheckConstraint("ck_payments_25", "hosted_invoice_ref IS NULL OR hosted_invoice_started_at IS NOT NULL");
                table.HasCheckConstraint("ck_payments_26", "(payment_method='crypto' AND quote_currency='USD' AND network_asset IS NOT NULL AND bank_destination IS NULL) OR\n           (payment_method='bank' AND quote_currency='TOMAN' AND order_id IS NOT NULL AND (bank_destination IS NOT NULL OR coalesce(legacy_kind='manual_deposit',false)) AND network_asset IS NULL AND network_amount IS NULL AND provider_confirmations IS NULL)");
                table.HasCheckConstraint("ck_payments_27", "topup_user_id IS NULL OR payment_method='crypto'");
                table.HasCheckConstraint("ck_payments_28", "status <> 'settled' OR confirmed_at IS NOT NULL");
                table.HasCheckConstraint("ck_payments_29", "num_nonnulls(ipn_key_id,ipn_signature,ipn_payload_sha256,ipn_verified_at) IN (0,4)");
                table.HasCheckConstraint("ck_payments_30", "ipn_key_id IS NULL OR (payment_method='crypto' AND provider_payment_ref IS NOT NULL AND expected_network_amount IS NOT NULL AND (evidence_asset_ref IS NOT NULL OR pending_evidence IS NOT NULL))");
                table.HasCheckConstraint("ck_payments_31", "expected_network_amount IS NULL OR payment_method='crypto'");
                table.HasCheckConstraint("ck_payments_32", "isfinite(ipn_verified_at)");
                table.HasCheckConstraint("ck_payments_33", "isfinite(first_payment_observed_at)");
                table.HasCheckConstraint("ck_payments_34", "isfinite(confirmed_at)");
                table.HasCheckConstraint("ck_payments_35", "isfinite(reviewed_at)");
                table.HasCheckConstraint("ck_payments_36", "isfinite(created_at)");
                table.HasCheckConstraint("ck_payments_37", "amount_due NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)");
                table.HasCheckConstraint("ck_payments_38", "amount_received NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)");
                table.HasCheckConstraint("ck_payments_39", "length(provider_code) BETWEEN 1 AND 160 AND btrim(provider_code)<>''");
                table.HasCheckConstraint("ck_payments_40", "length(provider_payment_ref) BETWEEN 1 AND 160 AND btrim(provider_payment_ref)<>''");
                table.HasCheckConstraint("ck_payments_41", "length(hosted_invoice_ref) BETWEEN 1 AND 160 AND btrim(hosted_invoice_ref)<>''");
                table.HasCheckConstraint("ck_payments_42", "length(hosted_invoice_url) BETWEEN 1 AND 1024 AND btrim(hosted_invoice_url)<>''");
                table.HasCheckConstraint("ck_payments_43", "length(idempotency_ref) BETWEEN 1 AND 160 AND btrim(idempotency_ref)<>''");
                table.HasCheckConstraint("ck_payments_44", "expected_network_amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)");
                table.HasCheckConstraint("ck_payments_45", "length(ipn_key_id) BETWEEN 1 AND 160 AND btrim(ipn_key_id)<>''");
                table.HasCheckConstraint("ck_payments_46", "network_amount NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)");
                table.HasCheckConstraint("ck_payments_47", "length(provider_status_code) BETWEEN 1 AND 160 AND btrim(provider_status_code)<>''");
                table.HasCheckConstraint("ck_payments_49", "length(receipt_asset_ref) BETWEEN 1 AND 1024 AND btrim(receipt_asset_ref)<>''");
                table.HasCheckConstraint("ck_payments_50", "length(review_reason)<=16384");
                table.HasCheckConstraint("ck_payments_51", "length(evidence_asset_ref) BETWEEN 1 AND 1024 AND btrim(evidence_asset_ref)<>''");
                table.HasCheckConstraint("ck_payments_53", "length(legacy_kind) BETWEEN 1 AND 160 AND btrim(legacy_kind)<>''");
            }
        });
        row.HasKey(v => v.Id);
        var id = row.Property(v => v.Id).HasColumnName("id").HasColumnType(sqlite ? "TEXT" : "uuid");
        id.IsRequired();
        id.ValueGeneratedNever();
        if (sqlite) id.UseCollation("NOCASE");
        var order_id = row.Property(v => v.OrderId).HasColumnName("order_id").HasColumnType(sqlite ? "TEXT" : "uuid");
        order_id.ValueGeneratedNever();
        if (sqlite) order_id.UseCollation("NOCASE");
        var topup_user_id = row.Property(v => v.TopupUserId).HasColumnName("topup_user_id").HasColumnType(sqlite ? "TEXT" : "uuid");
        topup_user_id.ValueGeneratedNever();
        if (sqlite) topup_user_id.UseCollation("NOCASE");
        var payment_method = row.Property(v => v.PaymentMethod).HasColumnName("payment_method").HasColumnType(sqlite ? "TEXT" : "text");
        payment_method.IsRequired();
        var quote_currency = row.Property(v => v.QuoteCurrency).HasColumnName("quote_currency").HasColumnType(sqlite ? "TEXT" : "text");
        quote_currency.IsRequired();
        var amount_due = row.Property(v => v.AmountDue).HasColumnName("amount_due").HasColumnType(sqlite ? "TEXT" : "numeric");
        amount_due.IsRequired();
        if (sqlite) amount_due.Metadata.SetTypeMapping(ExactSqliteDecimalMapping.Instance);
        var amount_received = row.Property(v => v.AmountReceived).HasColumnName("amount_received").HasColumnType(sqlite ? "TEXT" : "numeric");
        if (sqlite) amount_received.Metadata.SetTypeMapping(ExactSqliteDecimalMapping.Instance);
        var provider_code = row.Property(v => v.ProviderCode).HasColumnName("provider_code").HasColumnType(sqlite ? "TEXT" : "text");
        provider_code.HasMaxLength(160);
        var provider_payment_ref = row.Property(v => v.ProviderPaymentRef).HasColumnName("provider_payment_ref").HasColumnType(sqlite ? "TEXT" : "text");
        provider_payment_ref.HasMaxLength(160);
        var hosted_invoice_started_at = row.Property(v => v.HostedInvoiceStartedAt).HasColumnName("hosted_invoice_started_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        if (sqlite) hosted_invoice_started_at.HasConversion(EfValues.UtcTime);
        var hosted_invoice_ref = row.Property(v => v.HostedInvoiceRef).HasColumnName("hosted_invoice_ref").HasColumnType(sqlite ? "TEXT" : "text");
        hosted_invoice_ref.HasMaxLength(160);
        var hosted_invoice_url = row.Property(v => v.HostedInvoiceUrl).HasColumnName("hosted_invoice_url").HasColumnType(sqlite ? "TEXT" : "text");
        hosted_invoice_url.HasMaxLength(1024);
        var idempotency_ref = row.Property(v => v.IdempotencyRef).HasColumnName("idempotency_ref").HasColumnType(sqlite ? "TEXT" : "text");
        idempotency_ref.IsRequired();
        idempotency_ref.HasMaxLength(160);
        var network_asset = row.Property(v => v.NetworkAsset).HasColumnName("network_asset").HasColumnType(sqlite ? "TEXT" : "text");
        var expected_network_amount = row.Property(v => v.ExpectedNetworkAmount).HasColumnName("expected_network_amount").HasColumnType(sqlite ? "TEXT" : "numeric");
        if (sqlite) expected_network_amount.Metadata.SetTypeMapping(ExactSqliteDecimalMapping.Instance);
        var ipn_key_id = row.Property(v => v.IpnKeyId).HasColumnName("ipn_key_id").HasColumnType(sqlite ? "TEXT" : "text");
        ipn_key_id.HasMaxLength(160);
        var ipn_signature = row.Property(v => v.IpnSignature).HasColumnName("ipn_signature").HasColumnType(sqlite ? "BLOB" : "bytea");
        var ipn_payload_sha256 = row.Property(v => v.IpnPayloadSha256).HasColumnName("ipn_payload_sha256").HasColumnType(sqlite ? "BLOB" : "bytea");
        var ipn_verified_at = row.Property(v => v.IpnVerifiedAt).HasColumnName("ipn_verified_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        if (sqlite) ipn_verified_at.HasConversion(EfValues.UtcTime);
        var network_amount = row.Property(v => v.NetworkAmount).HasColumnName("network_amount").HasColumnType(sqlite ? "TEXT" : "numeric");
        if (sqlite) network_amount.Metadata.SetTypeMapping(ExactSqliteDecimalMapping.Instance);
        var provider_confirmations = row.Property(v => v.ProviderConfirmations).HasColumnName("provider_confirmations").HasColumnType(sqlite ? "INTEGER" : "bigint");
        var first_payment_observed_at = row.Property(v => v.FirstPaymentObservedAt).HasColumnName("first_payment_observed_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        if (sqlite) first_payment_observed_at.HasConversion(EfValues.UtcTime);
        var confirmed_at = row.Property(v => v.ConfirmedAt).HasColumnName("confirmed_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        if (sqlite) confirmed_at.HasConversion(EfValues.UtcTime);
        var status = row.Property(v => v.Status).HasColumnName("status").HasColumnType(sqlite ? "TEXT" : "text");
        status.IsRequired();
        status.HasDefaultValueSql(sqlite ? "'created'" : "'created'");
        var provider_status_code = row.Property(v => v.ProviderStatusCode).HasColumnName("provider_status_code").HasColumnType(sqlite ? "TEXT" : "text");
        provider_status_code.HasMaxLength(160);
        row.Ignore(v => v.BankDestinationCiphertext);
        var bank_destination = row.Property(v => v.BankDestination).HasColumnName("bank_destination").HasColumnType(sqlite ? "BLOB" : "bytea");
        row.Ignore(v => v.BankDestinationKeyId);
        var receipt_asset_ref = row.Property(v => v.ReceiptAssetRef).HasColumnName("receipt_asset_ref").HasColumnType(sqlite ? "TEXT" : "text");
        receipt_asset_ref.HasMaxLength(1024);
        var review_admin_id = row.Property(v => v.ReviewAdminId).HasColumnName("review_admin_id").HasColumnType(sqlite ? "TEXT" : "uuid");
        review_admin_id.ValueGeneratedNever();
        if (sqlite) review_admin_id.UseCollation("NOCASE");
        var reviewed_at = row.Property(v => v.ReviewedAt).HasColumnName("reviewed_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        if (sqlite) reviewed_at.HasConversion(EfValues.UtcTime);
        var review_reason = row.Property(v => v.ReviewReason).HasColumnName("review_reason").HasColumnType(sqlite ? "TEXT" : "text");
        review_reason.HasMaxLength(16384);
        var compensating_wallet_entry_id = row.Property(v => v.CompensatingWalletEntryId).HasColumnName("compensating_wallet_entry_id").HasColumnType(sqlite ? "TEXT" : "uuid");
        compensating_wallet_entry_id.ValueGeneratedNever();
        if (sqlite) compensating_wallet_entry_id.UseCollation("NOCASE");
        var evidence_asset_ref = row.Property(v => v.EvidenceAssetRef).HasColumnName("evidence_asset_ref").HasColumnType(sqlite ? "TEXT" : "text");
        evidence_asset_ref.HasMaxLength(1024);
        row.Ignore(v => v.PendingEvidenceCiphertext);
        var pending_evidence = row.Property(v => v.PendingEvidence).HasColumnName("pending_evidence").HasColumnType(sqlite ? "BLOB" : "bytea");
        row.Ignore(v => v.PendingEvidenceKeyId);
        var evidence_digest = row.Property(v => v.EvidenceDigest).HasColumnName("evidence_digest").HasColumnType(sqlite ? "BLOB" : "bytea");
        var legacy_kind = row.Property(v => v.LegacyKind).HasColumnName("legacy_kind").HasColumnType(sqlite ? "TEXT" : "text");
        legacy_kind.HasMaxLength(160);
        var created_at = row.Property(v => v.CreatedAt).HasColumnName("created_at").HasColumnType(sqlite ? "TEXT" : "timestamptz");
        created_at.IsRequired();
        created_at.HasDefaultValueSql(sqlite ? "(strftime('%Y-%m-%dT%H:%M:%f','now') || '0000Z')" : "CURRENT_TIMESTAMP");
        if (sqlite) created_at.HasConversion(EfValues.UtcTime);
        row.HasIndex(v => v.HostedInvoiceRef).IsUnique();
        row.HasIndex(v => v.IdempotencyRef).IsUnique();
        row.HasIndex(v => v.CompensatingWalletEntryId).IsUnique();
        row.HasOne<Order>().WithMany().HasForeignKey(v => v.OrderId).HasPrincipalKey(v => v.Id).OnDelete(DeleteBehavior.Restrict).HasConstraintName("payments_order_id_fk").HasAnnotation("Akanti:Deferrability", "DEFERRABLE INITIALLY IMMEDIATE");
        row.HasOne<User>().WithMany().HasForeignKey(v => v.TopupUserId).HasPrincipalKey(v => v.Id).OnDelete(DeleteBehavior.Restrict).HasConstraintName("payments_topup_user_id_fk").HasAnnotation("Akanti:Deferrability", "DEFERRABLE INITIALLY IMMEDIATE");
        row.HasOne<Admin>().WithMany().HasForeignKey(v => v.ReviewAdminId).HasPrincipalKey(v => v.Id).OnDelete(DeleteBehavior.Restrict).HasConstraintName("payments_review_admin_id_fk").HasAnnotation("Akanti:Deferrability", "DEFERRABLE INITIALLY IMMEDIATE");
        row.HasOne<WalletEntry>().WithMany().HasForeignKey(v => v.CompensatingWalletEntryId).HasPrincipalKey(v => v.Id).OnDelete(DeleteBehavior.Restrict).HasConstraintName("payments_compensating_wallet_entry_id_fk").HasAnnotation("Akanti:Deferrability", "DEFERRABLE INITIALLY IMMEDIATE");
        row.HasIndex(v => new { v.ProviderCode, v.ProviderPaymentRef }).HasDatabaseName("payments_provider_identity").IsUnique().HasFilter(sqlite ? "provider_payment_ref IS NOT NULL" : "provider_payment_ref IS NOT NULL");
    }
}
